package com.employeesystem.emsbackend.service; import com.employeesystem.emsbackend.dto.*; import com.employeesystem.emsbackend.entity.CalendarEvent; import com.employeesystem.emsbackend.repository.CalendarEventRepository; import jakarta.persistence.EntityNotFoundException; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import java.util.List;
@Service @RequiredArgsConstructor public class CalendarEventService { private final CalendarEventRepository repository; private CalendarEventResponseDTO map(CalendarEvent e){return new CalendarEventResponseDTO(e.getId(),e.getTitle(),e.getEventDate(),e.getType(),e.getDescription());} public List<CalendarEventResponseDTO> list(){return repository.findAll().stream().sorted(java.util.Comparator.comparing(CalendarEvent::getEventDate)).map(this::map).toList();} public CalendarEventResponseDTO create(CalendarEventRequestDTO r){CalendarEvent e=new CalendarEvent();e.setTitle(r.title());e.setEventDate(r.eventDate());e.setType(r.type());e.setDescription(r.description());return map(repository.save(e));} public void delete(Long id){repository.delete(repository.findById(id).orElseThrow(()->new EntityNotFoundException("Calendar event not found")));} }
